          "format": "condition",
          "text": "Bank account numbers are stored encrypted at rest."
        },
        {
          "id": "US-01-AC03",
          "format": "given_when_then",
          "text": "Given a new customer record with all mandatory fields, when the record is saved, then the system assigns a unique Customer-ID."
        }
      ]
    },
    {
      "id": "US-02",
      "type": "functional",
      "statement": "As a Customer, I want to browse the product catalog, so that I can decide what to buy.",
      "acceptance_criteria": [
        {
          "id": "US-02-AC01",
          "format": "condition",
          "text": "Each product has a name, description, price (decimal) and image URL."
