      "acceptance_criteria": [
        {
          "id": "US-10-AC01",
          "format": "given_when_then",
          "text": "Given an Invoice with status issued, when a Customer submits a Payment (date, amount, payment method), then a Payment record with status pending is created and linked to the Invoice."
        },
        {
          "id": "US-10-AC02",
          "format": "condition",
          "text": "Payment method must be one of {bank, card, cash}."
        },
        {
          "id": "US-10-AC03",
          "format": "given_when_then",
          "text": "Given an Invoice with status paid, when a Payment is submitted, then the system rejects the submission."
        }
      ]
    },
    {
