        },
        {
          "id": "US-11-AC02",
          "format": "condition",
          "text": "Payment status may only change from pending to completed or failed."
        },
        {
          "id": "US-11-AC03",
          "format": "given_when_then",
          "text": "Given a Payment whose status is failed, when Accountant attempts to confirm it, then the request is rejected and the status stays failed."
        }
      ]
    },
    {
