      "type": "functional",
      "statement": "As a Customer, I want the system to calculate the total amount of my order automatically, so that I know how much I will be charged.",
      "acceptance_criteria": [
        {
          "id": "US-04-AC01",
          "format": "condition",
          "text": "Order total = Σ (order-item.quantity × order-item.unit-price)."
        },
        {
          "id": "US-04-AC02",
          "format": "given_when_then",
          "text": "Given a successfully created Order, when the total is queried, then the returned total equals the calculated sum."
        },
        {
          "id": "US-04-AC03",
          "format": "condition",
          "text": "Unit price is stored as a decimal."
        }
      ]
    },
    {
      "id": "US-05",
      "type": "functional",
      "statement": "As an OrderStaff, I want to receive a submitted order, so that it can move to the pending state for further processing.",
      "acceptance_criteria": [
        {
          "id": "US-05-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status submitted, when OrderStaff clicks Receive, then the Order status becomes pending."
        },
        {
          "id": "US-05-AC02",
          "format": "condition",
          "text": "The status transition submitted → pending is the only allowed transition from submitted."
        },
        {
          "id": "US-05-AC03",
          "format": "given_when_then",
          "text": "Given an Order whose status is filled, when OrderStaff attempts to receive it, then the system rejects the request and leaves the status unchanged."
        }
      ]
    },
    {
      "id": "US-06",
      "type": "functional",
      "statement": "As an OrderStaff, I want to mark a pending order as filled, so that the items can be prepared for shipping.",
      "acceptance_criteria": [
        {
          "id": "US-06-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status pending, when OrderStaff selects Mark as Filled, then the Order status becomes filled."
        },
        {
          "id": "US-06-AC02",
          "format": "condition",
          "text": "No transition is allowed from pending to any status other than filled or closed."
        },
        {
          "id": "US-06-AC03",
          "format": "given_when_then",
          "text": "Given an Order with status submitted, when OrderStaff attempts to fill it, then the request is rejected and the status stays submitted."
        }
      ]
    },
    {
      "id": "US-07",
      "type": "functional",
      "statement": "As an OrderStaff, I want to decline a pending order, so that the order is closed without further processing.",
      "acceptance_criteria": [
        {
          "id": "US-07-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status pending, when OrderStaff selects Decline, then the Order status becomes closed."
        },
        {
          "id": "US-07-AC02",
          "format": "condition",
          "text": "Decline is only permitted from pending."
        },
        {
          "id": "US-07-AC03",
          "format": "given_when_then",
          "text": "Given an Order with status filled, when OrderStaff attempts to decline, then the system rejects the request."
        }
      ]
    },
    {
      "id": "US-08",
      "type": "functional",
      "statement": "As an OrderStaff, I want to ship a filled order, so that the customer receives the goods.",
      "acceptance_criteria": [
        {
          "id": "US-08-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status filled, when OrderStaff selects Ship, then the Order status becomes shipped."
        },
        {
          "id": "US-08-AC02",
          "format": "condition",
          "text": "Transition filled → shipped is the only allowed transition from filled."
        },
        {
          "id": "US-08-AC03",
          "format": "given_when_then",
          "text": "Given an Order with status pending, when OrderStaff attempts to ship, then the request is rejected and the status remains pending."
        }
      ]
    },
    {
      "id": "US-09",
      "type": "functional",
      "statement": "As an Accountant, I want to raise an invoice for a filled or shipped order that has no invoice yet, so that the customer can be billed.",
      "acceptance_criteria": [
        {
          "id": "US-09-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status filled or shipped and no existing Invoice, when Accountant creates an Invoice (date, amount, payment method), then an Invoice with status issued is linked to the Order."
        },
        {
          "id": "US-09-AC02",
          "format": "condition",
          "text": "Only one Invoice may exist per Order."
        },
        {
          "id": "US-09-AC03",
          "format": "given_when_then",
          "text": "Given an Order whose status is submitted, pending or closed, when Accountant tries to raise an Invoice, then the request is rejected."
        }
      ]
    },
    {
      "id": "US-10",
      "type": "functional",
      "statement": "As an Accountant, I want to record a payment against an issued invoice, so that the invoice can be settled.",
      "acceptance_criteria": [
        {
          "id": "US-10-AC01",
          "format": "given_when_then",
          "text": "Given an Invoice with status issued, when a Customer submits a Payment (date, amount, payment method), then a Payment record with status pending is created and linked to the Invoice."
        },
        {
          "id": "US-10-AC02",
          "format": "condition",
          "text": "Payment method must be one of {bank, card, cash}."
        },
        {
          "id": "US-10-AC03",
          "format": "given_when_then",
          "text": "Given an Invoice with status paid, when a Payment is submitted, then the system rejects the submission."
        }
      ]
    },
    {
      "id": "US-11",
      "type": "functional",
      "statement": "As an Accountant, I want to confirm a pending payment, so that the related invoice becomes paid.",
      "acceptance_criteria": [
        {
          "id": "US-11-AC01",
          "format": "given_when_then",
          "text": "Given a Payment with status pending, when Accountant marks it completed, then the Payment status becomes completed and the linked Invoice status becomes paid."
        },
        {
          "id": "US-11-AC02",
          "format": "condition",
          "text": "Payment status may only change from pending to completed or failed."
        },
        {
          "id": "US-11-AC03",
          "format": "given_when_then",
          "text": "Given a Payment whose status is failed, when Accountant attempts to confirm it, then the request is rejected and the status stays failed."
        }
      ]
    },
    {
      "id": "US-12",
      "type": "functional",
      "statement": "As an Accountant, I want to reject a pending payment, so that the customer can try again.",
      "acceptance_criteria": [
        {
          "id": "US-12-AC01",
          "format": "given_when_then",
          "text": "Given a Payment with status pending, when Accountant marks it failed, then the Payment status becomes failed; the Invoice status remains unchanged."
        },
        {
          "id": "US-12-AC02",
          "format": "condition",
          "text": "Only payments in pending may be rejected."
        },
        {
          "id": "US-12-AC03",
          "format": "given_when_then",
          "text": "Given a Payment with status completed, when Accountant attempts to reject it, then the request is rejected."
        }
      ]
    },
    {
      "id": "US-13",
      "type": "functional",
      "statement": "As an OrderStaff, I want to close a shipped order whose invoice is paid, so that the order lifecycle ends.",
      "acceptance_criteria": [
        {
          "id": "US-13-AC01",
          "format": "given_when_then",
          "text": "Given an Order with status shipped and a linked Invoice with status paid, when OrderStaff selects Close, then the Order status becomes closed."
        },
        {
          "id": "US-13-AC02",
          "format": "condition",
          "text": "Closing is only allowed from shipped when the Invoice is paid."
        },
        {
          "id": "US-13-AC03",
          "format": "given_when_then",
          "text": "Given a shipped Order whose Invoice is not paid, when OrderStaff attempts to close, then the request is rejected and the status stays shipped."
        }
      ]
    },
    {
      "id": "US-14",
      "type": "functional",
      "statement": "As a Customer, OrderStaff, or Accountant, I want the system to enforce mandatory attributes and allowed value sets, so that data integrity is guaranteed.",
      "acceptance_criteria": [
        {
          "id": "US-14-AC01",
          "format": "condition",
          "text": "All attributes except Customer.bankAccount are mandatory."
        },
